    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Estúdios da NESE reservados a profissionais com mais de 30 anos, localizados em Back Bay, um dos bairros mais valorizados de Boston. As unidades ficam no nível do jardim de brownstones históricos, típicos da região, e estão a uma curta caminhada da escola e das principais atrações do centro. É a opção mais independente da NESE: apartamento próprio, sem colegas de quarto, com liberdade total de horários e possibilidade de cozinhar e receber o próprio ritmo de trabalho e estudo. Nesta opção você fica em quarto individual com banheiro privativo, de uso exclusivo. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar. Estadia mínima de 4 semanas.</p><p>Suplementos e condições: Noite extra: USD 220; Depósito caução (reembolsável): USD 500.</p><p>Tabela oficial NESE Dates &amp; Fees 2026 (valida até dez/2026): a hospedagem e cobrada por sessao de 4 semanas e o valor semanal equivale ao total dividido por 4. Disponível de 4 a 48 semanas (1 a 12 sessões). Não ha taxa de colocação de acomodacao. A NESE fecha na última semana de abril, na última de agosto e nas duas ultimas de dezembro; quem permanece na hospedagem nesses períodos paga de US$55 (quarto compartilhado) a US$220 (quarto individual) por noite. Garantia de acomodacao reembolsável de US$250 (US$500 no apartamento), cobrada apenas se o contrato de hospedagem não for cumprido. Não ha suplemento de alta temporada nem desconto de baixa temporada publicados. Apartamento: US$3.110 por sessao de 4 semanas, ou seja US$777,50 por semana, sem refeições. Garantia de acomodacao de US$500.</p>','["Estúdio Privativo", "Somente Profissionais 30+", "Back Bay, Boston", "Curta Caminhada até a Escola", "Privacidade Total", "Independência de Horários", "Brownstone Histórico", "Quarto Individual", "Banheiro Privativo", "Self-catering", "Ideal para profissionais acima de 30 anos que querem privacidade total", "Ideal para quem combina trabalho e curso e precisa de espaço próprio", "Ideal para quem quer morar no centro de Boston, a pé da escola", "Ideal para quem prefere cozinhar e viver de forma independente", "Ideal para quem valoriza privacidade total e silêncio para estudar", "Ideal para quem prefere não dividir banheiro com ninguém", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para estudantes com menos de 30 anos (não elegíveis)", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem quer socializar diariamente com outros estudantes", "Menos indicado para quem procura a opção mais econômica", "Menos indicado para quem procura a alternativa mais barata", "Menos indicado para quem quer dividir o quarto com um amigo para reduzir custos", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
