    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da New England School of English (NESE) em Boston: famílias americanas cuidadosamente selecionadas pela escola, com bastante experiência em receber estudantes internacionais. A NESE trabalha com uma variedade de arranjos que refletem a realidade americana (casais, pessoas que moram sozinhas, famílias com ou sem filhos), o que dá uma visão realista da cultura local. Todos os homestays oferecem quarto individual com café da manhã e jantar todos os dias, e a escola dá muita atenção ao pareamento porque considera o conforto em casa essencial para o rendimento em sala. Vale saber o que o anfitrião normalmente não fornece: serviço de camareira, lavagem de roupas, TV/DVD privativo, transporte, lugar para amigos e parentes dormirem, comida para levar de almoço à escola ou espaço para fumar dentro de casa. Nesta opção o quarto é duplo/twin (para quem viaja acompanhado ou dividido com outro estudante do mesmo gênero) e o banheiro é compartilhado. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta. Estadia mínima de 4 semanas.</p><p>Suplementos e condições: Noite extra: USD 55; Depósito caução (reembolsável): USD 250.</p><p>Tabela oficial NESE Dates &amp; Fees 2026 (valida até dez/2026): a hospedagem e cobrada por sessao de 4 semanas e o valor semanal equivale ao total dividido por 4. Disponível de 4 a 48 semanas (1 a 12 sessões). Não ha taxa de colocação de acomodacao. A NESE fecha na última semana de abril, na última de agosto e nas duas ultimas de dezembro; quem permanece na hospedagem nesses períodos paga de US$55 (quarto compartilhado) a US$220 (quarto individual) por noite. Garantia de acomodacao reembolsável de US$250 (US$500 no apartamento), cobrada apenas se o contrato de hospedagem não for cumprido. Não ha suplemento de alta temporada nem desconto de baixa temporada publicados. ATENCAO: este produto não consta na tabela oficial NESE 2026, que publica apenas Homestay quarto individual, Dormitorio individual, Dormitorio compartilhado e Apartamento. Valor zerado até confirmação com a escola.</p>','["Famílias Americanas Selecionadas", "Quarto Individual", "Café da Manhã e Jantar Diários", "Pareamento Cuidadoso", "Imersão Cultural", "Prática Diária de Inglês", "Perto de Transporte Público", "Quarto Duplo/Twin", "Banheiro Compartilhado", "Meia Pensão", "Ideal para quem quer conviver com americanos e praticar inglês todos os dias", "Ideal para quem prefere ter café da manhã e jantar garantidos", "Ideal para quem viaja sozinho e quer um ambiente acolhedor", "Ideal para quem quer entender a cultura dos EUA de dentro de uma casa", "Ideal para quem viaja acompanhado ou quer dividir custos", "Ideal para quem gosta de socializar e não se importa em dividir espaços", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem espera serviço de hotel (camareira, lavanderia, transporte)", "Menos indicado para quem quer cozinhar e ter liberdade total de horários", "Menos indicado para quem quer receber visitas para dormir", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem precisa de privacidade e silêncio", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
    insert into price_template (tenant_id, campus_id, name, price_basis, duration_type, unit, currency, charge_in_tiers, valid_from, status) values (v_tid,'2149002c-893b-5f23-a4c4-aadfcbeccb7f','Casa de família — quarto compartilhado, banheiro compartilhado, meia pensão','duration','flexible','week','USD',false,'2026-01-01','active') returning id into v_tpl;
